"""
TieredResolver — 3-tier cascade fact resolver.

Tier 1: SQLite KB lookup (free, <10ms) — distilled_facts DB + AtomicResolver
Tier 2: WebSearch stub (WebSearchResolver) — always None in current stub
Tier 3: LLM callable (budget-gated, max 20 calls per run)
"""

import hashlib
import sqlite3
from dataclasses import dataclass, field
from datetime import datetime
from pathlib import Path
from typing import Callable, Optional

from .web_search_resolver import WebSearchResolver


class BudgetController:
    def __init__(self, max_calls: int = 20):
        self.max_calls = max_calls
        self.calls_made = 0

    def can_spend(self) -> bool:
        return self.calls_made < self.max_calls

    def spend(self) -> None:
        self.calls_made += 1

    def remaining(self) -> int:
        return self.max_calls - self.calls_made


@dataclass
class ResolverStats:
    tier1_hits: int = 0
    tier2_hits: int = 0
    tier3_hits: int = 0
    unresolved: int = 0
    total_queries: int = 0

    @property
    def tier1_rate(self) -> float:
        return self.tier1_hits / max(self.total_queries, 1)

    @property
    def tier2_rate(self) -> float:
        return self.tier2_hits / max(self.total_queries, 1)

    @property
    def tier3_rate(self) -> float:
        return self.tier3_hits / max(self.total_queries, 1)

    def to_dict(self) -> dict:
        return {
            "tier1_hits": self.tier1_hits,
            "tier2_hits": self.tier2_hits,
            "tier3_hits": self.tier3_hits,
            "unresolved": self.unresolved,
            "total_queries": self.total_queries,
            "tier1_rate": round(self.tier1_rate, 3),
            "tier2_rate": round(self.tier2_rate, 3),
            "tier3_rate": round(self.tier3_rate, 3),
        }


def _hash_query(text: str) -> str:
    return hashlib.sha256(text.lower().strip().encode()).hexdigest()


def _now_iso() -> str:
    return datetime.utcnow().isoformat()


class TieredResolver:
    """
    3-tier cascade resolver for micro-queries.

    Accepts any object with .text and .dimension attributes, or plain strings.
    Returns list of dicts (avoids circular import with models.py from Phase 1).
    """

    def __init__(
        self,
        vectors_db: Optional[Path] = None,
        distilled_db: Optional[Path] = None,
        research_fn: Optional[Callable[[str], Optional[str]]] = None,
        llm_budget: int = 20,
    ):
        self.vectors_db = vectors_db
        self.distilled_db = distilled_db
        self.research_fn = research_fn
        self.budget = BudgetController(llm_budget)
        self.stats = ResolverStats()
        self._web_resolver = WebSearchResolver()

        # Lazy-load AtomicResolver only when vectors_db is available
        self._atomic_resolver = None
        if vectors_db and vectors_db.exists():
            self._atomic_resolver = self._try_load_atomic_resolver(vectors_db)

    # ------------------------------------------------------------------
    # Public API
    # ------------------------------------------------------------------

    def resolve_batch(self, queries: list) -> list[dict]:
        """Resolve a batch of queries through the 3-tier cascade."""
        self.stats = ResolverStats()  # reset per batch
        self.stats.total_queries = len(queries)
        return [self._resolve_single(q) for q in queries]

    @property
    def web_resolver(self) -> WebSearchResolver:
        """Expose web resolver so callers can inject WebSearch results."""
        return self._web_resolver

    # ------------------------------------------------------------------
    # Internal cascade
    # ------------------------------------------------------------------

    def _resolve_single(self, query) -> dict:
        query_text = query if isinstance(query, str) else query.text
        query_hash = _hash_query(query_text)

        # Tier 1: local KB
        t1 = self._tier1_resolve(query_text, query_hash)
        if t1:
            self.stats.tier1_hits += 1
            return t1

        # Tier 2: WebSearch (stub — always None unless injected)
        t2 = self._web_resolver.resolve(query_text)
        if t2:
            self.stats.tier2_hits += 1
            return {
                "query_text": query_text,
                "query_hash": query_hash,
                "fact_value": t2.get("fact_value"),
                "confidence": "[T]",
                "source_tier": 2,
                "source_url": t2.get("source_url"),
                "source_name": "websearch",
                "resolved_at": _now_iso(),
                "cost_usd": 0.001,
            }

        # Tier 3: LLM (budget-gated)
        if self.budget.can_spend() and self.research_fn:
            try:
                result = self.research_fn(query_text)
                self.budget.spend()
                self.stats.tier3_hits += 1
                return {
                    "query_text": query_text,
                    "query_hash": query_hash,
                    "fact_value": str(result) if result else None,
                    "confidence": "[T]" if result else "[?]",
                    "source_tier": 3,
                    "source_url": None,
                    "source_name": "llm",
                    "resolved_at": _now_iso(),
                    "cost_usd": 0.01,
                }
            except Exception:
                pass

        # Unresolved
        self.stats.unresolved += 1
        return {
            "query_text": query_text,
            "query_hash": query_hash,
            "fact_value": None,
            "confidence": "[?]",
            "source_tier": 0,
            "source_url": None,
            "source_name": None,
            "resolved_at": _now_iso(),
            "cost_usd": 0.0,
        }

    def _tier1_resolve(self, query_text: str, query_hash: str) -> Optional[dict]:
        """Check distilled_facts DB first, then AtomicResolver."""
        now = _now_iso()

        # 1a. distilled_facts table
        if self.distilled_db and self.distilled_db.exists():
            row = self._query_distilled_db(query_hash)
            if row:
                fact_value, confidence, source_url = row
                return {
                    "query_text": query_text,
                    "query_hash": query_hash,
                    "fact_value": fact_value,
                    "confidence": confidence or "[K]",
                    "source_tier": 1,
                    "source_url": source_url,
                    "source_name": "distilled_facts",
                    "resolved_at": now,
                    "cost_usd": 0.0,
                }

        # 1b. AtomicResolver
        if self._atomic_resolver:
            result = self._query_atomic_resolver(query_text, now)
            if result:
                return result

        return None

    def _query_distilled_db(self, query_hash: str) -> Optional[tuple]:
        try:
            with sqlite3.connect(str(self.distilled_db)) as conn:
                row = conn.execute(
                    "SELECT fact_value, confidence, source_url FROM distilled_facts WHERE query_hash = ?",
                    (query_hash,),
                ).fetchone()
                if row and row[0]:
                    return row
        except sqlite3.OperationalError:
            pass  # table doesn't exist yet — treat as miss
        return None

    def _query_atomic_resolver(self, query_text: str, now: str) -> Optional[dict]:
        try:
            import sys
            sys.path.insert(0, str(Path(__file__).resolve().parents[2]))
            from intelligence.reasoning.problem_decomposer import AtomicQuestion
            aq = AtomicQuestion(text=query_text, category="custom", priority=1)
            resolution = self._atomic_resolver.resolve(aq, {})
            if resolution.status == "RESOLVED" and resolution.confidence >= 0.6:
                return {
                    "query_text": query_text,
                    "query_hash": _hash_query(query_text),
                    "fact_value": resolution.answer,
                    "confidence": "[K]",
                    "source_tier": 1,
                    "source_url": None,
                    "source_name": f"atomic_resolver:{resolution.source}",
                    "resolved_at": now,
                    "cost_usd": 0.0,
                }
        except Exception:
            pass
        return None

    @staticmethod
    def _try_load_atomic_resolver(vectors_db: Path):
        try:
            import sys
            sys.path.insert(0, str(vectors_db.resolve().parents[4] / ".claude" / "lib"))
            from intelligence.reasoning.atomic_resolver import AtomicResolver
            return AtomicResolver(vectors_db=vectors_db)
        except Exception:
            return None
